Here's the code for a Discord.js v14 bot with a ban command using slash commands:

1. Install required packages:
```bash
npm install discord.js
npm install @discordjs/rest
npm install @discordjs/builders
```

2. Create a new directory for your bot project and initialize a new Node.js project:
```bash
mkdir discord-bot
cd discord-bot
npm init -y
```

3. Create a `config.json` file in the root directory with the following contents:
```json
{
  "token": "<your bot token>",
  "clientId": "<your bot client ID>",
  "guildId": "<your server ID>"
}
```
Replace `<your bot token>`, `<your bot client ID>`, and `<your server ID>` with your own values. Your bot token can be obtained from the Discord Developers Portal, while your client ID and server ID can be found on their respective settings pages.

4. Create a `index.js` file in the root directory and paste the following code:

```javascript
// Import required modules
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const { Client, Intents, Collection } = require('discord.js');
const { config } = require('./config.json');

// Initialize Discord client
const client = new Client({ intents: [Intents.FLAGS.GUILDS] });

// Define command data for the ban command (must be registered before calling)
const banCommand = {
  name: 'ban',
  description: 'Bans a user from the server.',
  options: [
    {
      type: 'USER',
      name: 'target',
      description: 'The user to be banned.', 
      required: true,
    },
  ],
};

// Register commands on the client
client.commands = new Collection();
client.commands.set(banCommand.name, banCommand);
const rest = new REST({ version: '9' }).setToken(config.token);

(async () => {
  try {
    await rest.put(
      Routes.applicationCommands(config.clientId),
      { body: client.commands.map(c => c.toJSON()) },
    );

    console.log('Successfully registered commands.');
  } catch (error) {
    console.error(error);
  }
})();

// Listen for when the client is ready
client.once('ready', () => {
  console.log(`Bot is ready!`);
});

// Define command handler
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.guild.members.me?.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: "I don't have permission to ban members! Check my permissions and try again.",
        ephemeral: true,
      });
    }

    const target = interaction.options.getUser('target');

    if (!target) {
      return interaction.reply({
        content: "Invalid target specified. Make sure you specify a valid user.",
        ephemeral: true,
      });
    }

    try {
      await interaction.guild.members.ban(target.id, {
        reason: `Command: ${interaction.commandName}`,
      });
      interaction.reply({
        content: `Successfully banned ${target.tag}.`,
      });
    } catch (error) {
      interaction.reply({
        content: `Error banning ${target.tag}! \n${error}`,
      });
    }
  }
});

// Login the client
client.login(config.token);
```

This code registers your bot with the Discord API and sets up an event listener for when the `ban` command is used. Once the command is invoked, the bot checks if it has the `BAN_MEMBERS` permission, then attempts to ban the specified target. If successful, a message is sent to the channel; otherwise, an error message is displayed.

Make sure to replace the placeholders for `config.json` with your actual values before running the bot. Once done, you can run the bot using `node index.js` in your terminal.

