Writing a first-person controller script for a KinematicBody node in Godot Engine 3.x and adjusting it for Godot Engine 4.x requires making a few changes to the script. Here's the GDScript for the first-person controller in Godot Engine 3.x:

```
extends KinematicBody

export var speed := 10.0
export var mouse_sensitivity := 0.2
export var gravity := -10.0

var velocity := Vector3()
var camera := null
var input_vector := Vector2()

onready var ray_cast := $RayCast
onready var floor_normal := ray_cast.normal

func _ready():
	camera = $Camera

func _input(event):
	if event is InputEventMouseMotion:
		input_vector = event.relative

func _unhandled_input(event):
	if event is InputEventMouseMotion:
		camera.rotate_x(-input_vector.y * mouse_sensitivity)
		camera.rotate_y(-input_vector.x * mouse_sensitivity)
		camera.rotation.x = clamp(camera.rotation.x, -PI / 2, PI / 2)

func get_input_vector():
	var movement_vector := Vector3()

	if Input.is_action_pressed("move_forward"):
		movement_vector.z -= 1.0
	if Input.is_action_pressed("move_backward"):
		movement_vector.z += 1.0
	if Input.is_action_pressed("move_left"):
		movement_vector.x -= 1.0
	if Input.is_action_pressed("move_right"):
		movement_vector.x += 1.0

	return movement_vector.normalized()

func _physics_process(delta):
	input_vector = Vector2()
	var movement_vector := get_input_vector()

	velocity.x = movement_vector.x * speed
	velocity.z = movement_vector.z * speed

	velocity.y += gravity * delta

	velocity = move_and_slide(velocity, Vector3.UP, false, 4, PI / 4)

	if is_on_floor() and !is_on_wall():
		var jump_impulse = 5.0
		if Input.is_action_just_pressed("jump"):
			if floor_normal.y > 0.5:
				velocity.y = jump_impulse
```

